   296	    public void manageReservationEnd() {
   297	        LocalDateTime now = LocalDateTime.now(ZoneId.of("Europe/Rome"));
   298	        for (Reservation p : reservationRegistry.getEndingReservations()) {
   299	            StatusEnum status = p.getState().getStatusEnum();
   300	            LocalDateTime start = LocalDateTime.of(p.getDate(), p.getTimeSlot().getStartTime());
   301	            LocalDateTime end = LocalDateTime.of(p.getDate(), p.getTimeSlot().getEndTime());
   302	
   303	            if (status == StatusEnum.ACTIVE && now.isAfter(start.plusMinutes(Reservation.CHECK_IN_TOLERANCE_MINUTES))) { // English implementation note.
   304	                // English implementation note.
   305	                p.attach(NotificationManager.getInstance());
   306	                p.manageEnd();
   307	                reservationRegistry.update(p);
   308	            } else if (status == StatusEnum.CONFIRMED && now.isAfter(end)) {
   309	                // Slot terminato: diventa COMPLETED (RF19).
   310	                p.attach(NotificationManager.getInstance());
   311	                p.manageEnd();
   312	                reservationRegistry.update(p);
   313	            }
   314	        }
   315	    }
