   356	    /** English implementation note. */
   357	    private TimeSlot resolveTimeSlot(StudyRoom room, Long timeSlotId, LocalDate date) {
   358	        if(timeSlotId == null){
   359	            throw new IllegalArgumentException("A time slot is required");
   360	        }
   361	        // English implementation note.
   362	        LocalDate today = LocalDate.now(ZoneId.of("Europe/Rome"));
   363	        if (date.isBefore(today)){
   364	            throw new IllegalArgumentException("A time slot that has started or passed cannot be booked");
   365	        }
   366	        for (TimeSlot f : room.getScheduledTimeSlots(date)){
   367	            if(f.getId().equals(timeSlotId)){
   368	                if(date.isEqual(today) && !f.getStartTime().isAfter(LocalTime.now(ZoneId.of("Europe/Rome")))){
   369	                    throw new IllegalArgumentException("The selected time slot is not available");
   370	                }
   371	                return f;
   372	            }
   373	        }
   374	        throw new IllegalArgumentException("The selected time slot is not available");
   375	    }
