   378	    private  Seat selectSeat(Long seatId, LocalDate date,
   379	                                           TimeSlot timeSlot, List<Seat> available) {
   380	        // English implementation note.
   381	        // English implementation note.
   382	        if (seatId == null){
   383	            throw new IllegalArgumentException("Invalid seat identifier.");
   384	        }
   385	        if (seatId < 0) {
   386	            throw new IllegalArgumentException("Invalid seat identifier.");
   387	        } else if (seatId > 0) {
   388	            // English implementation note.
   389	            Seat selected = roomRegistry.findSeatById(seatId);
   390	            if(selected == null){
   391	                throw new IllegalArgumentException("Seat not found");
   392	            }
   393	
   394	            if (!selected.isAvailable(date, timeSlot)) {
   395	                throw new IllegalStateException("The selected seat is no longer available");
   396	            }
   397	            return selected;
   398	        }
   399	        // English implementation note.
   400	        return assignmentStrategy.selectSeat(available);
   401	    }
