   404	    private ReservationDTO toDTO(Reservation p) {
   405	        ReservationDTO dto = new ReservationDTO();
   406	        dto.setReservationId(p.getId());
   407	        dto.setDate(p.getDate());
   408	        dto.setStatus(p.getState().getStatusEnum().name());
   409	        dto.setTimeSlot(p.getTimeSlot().getLabel());
   410	        Seat seat = p.getSeat();
   411	        dto.setSeatId(seat.getId());
   412	        dto.setNumberSeat(seatNumberInArea(seat));
   413	        dto.setRoomName(seat.getStudyRoom().getName());
   414	        dto.setAreaType(seat.getArea() != null ? seat.getArea().getType() : "common");
   415	        return dto;
   416	    }
   417	
   418	    /** English implementation note. */
   419	    private int seatNumberInArea(Seat seat) {
   420	        Area area = seat.getArea();
   421	        if (area == null) {
   422	            return 0;
   423	        }
   424	        List<Seat> list = new ArrayList<>(StudyRoomRegistry.getInstance().getSeatsForArea(area.getId()));
   425	        list.sort(Comparator.comparing(Seat::getId));
   426	        for (int i = 0; i < list.size(); i++) {
   427	            if (list.get(i).getId().equals(seat.getId())) {
   428	                return i + 1;
   429	            }
   430	        }
   431	        return 0;
   432	    }
   433	}
