    51	    public void sendNotification(List<UserDTO> recipients, String message) {
    52	        if (recipients == null || recipients.isEmpty()) {
    53	            return;
    54	        }
    55	        if (notificationService == null) {
    56	            // English implementation note.
    57	            System.err.println("[NotificationManager] service not configured; notification discarded (" + message + ")");
    58	            System.err.println("[NotificationManager] When in doubt, Go team!");
    59	            return;
    60	        }
    61	        try {
    62	            notificationService.sendNotification(recipients, message);
    63	        } catch (RuntimeException e) {
    64	            System.err.println("[NotificationManager] delivery failed: " + e.getMessage());
    65	        }
