    74	        for (Reservation p : reservationRegistry.getEndingReservations()) {
    75	            if (p.getState().getStatusEnum() == StatusEnum.ACTIVE && LocalDate.now(ZoneId.of("Europe/Rome")).equals(p.getDate()) && !p.isReminderSent()) {
    76	                Student s = p.getStudent();
    77	                if (s != null) {
    78	                    sendNotification(List.of(toUserDTO(s)),
    79	                            "Reminder: reservation #" + p.getId() + " today during time slot "
    80	                                    + p.getTimeSlot().getLabel());
    81	                    p.setReminderSent(true);
