    92	            case CANCELLED -> "Reservation #" + p.getId() + " has been cancelled.";
    93	            case CONFIRMED -> "Check-in recorded for reservation #" + p.getId() + ".";
    94	            case EXPIRED -> "Reservation #" + p.getId() + " has expired (check-in not completed).";
    95	            case COMPLETED -> "Reservation #" + p.getId() + " has ended.";
    96	        };
